import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// Settings come from the same files `make up` uses: config/local.env, an optional
// config/override.env, then .local/credentials.env (generated by scripts/secrets.sh).
// A variable already set in the environment wins, so DOMAIN=... works.
const here = path.dirname(fileURLToPath(import.meta.url));
export const repoRoot = path.resolve(here, "..", "..", "..");

function readEnvFile(file: string): Record<string, string> {
  if (!existsSync(file)) return {};
  const out: Record<string, string> = {};
  for (const line of readFileSync(file, "utf8").split("\n")) {
    const t = line.trim();
    if (!t || t.startsWith("#")) continue;
    const eq = t.indexOf("=");
    if (eq > 0) out[t.slice(0, eq)] = t.slice(eq + 1);
  }
  return out;
}

const files = {
  ...readEnvFile(path.join(repoRoot, "config", "local.env")),
  ...readEnvFile(path.join(repoRoot, "config", "override.env")),
  ...readEnvFile(path.join(repoRoot, ".local", "credentials.env")),
};
const get = (key: string): string => process.env[key] ?? files[key] ?? "";

function need(key: string): string {
  const v = get(key);
  if (!v) throw new Error(`${key} is not set; run \`make up\` (scripts/secrets.sh writes .local/credentials.env)`);
  return v;
}

export const domain = get("DOMAIN") || "lab.localhost";
const httpsPort = get("HTTPS_PORT") || "443";
const portSuffix = httpsPort === "443" ? "" : `:${httpsPort}`;

/** Origin of a host in the lab, for example url("storage") -> https://storage.lab.localhost */
export const url = (host?: string): string => `https://${host ? `${host}.` : ""}${domain}${portSuffix}`;
export const origin = url;

export type UserName = "admin" | "alice" | "bob";
export const users: Record<UserName, { name: string; password: string }> = {
  admin: { name: get("ADMIN_USER") || "admin", password: need("ADMIN_PASSWORD") },
  alice: { name: "alice", password: need("ALICE_PASSWORD") },
  bob: { name: "bob", password: need("BOB_PASSWORD") },
};

export const authDir = path.resolve(here, "..", ".auth");
export const statePath = (u: UserName): string => path.join(authDir, `${u}.json`);

/** A short id so concurrent or leftover runs never collide on names. */
export const runId = (process.env.E2E_RUN_ID ?? Date.now().toString(36)).slice(-8);
